const express = require('express');
const session = require('express-session');
const RedisStore = require('connect-redis').default;
const Redis = require('ioredis');

const app = express();
const redisClient = new Redis(process.env.REDIS_URL);
const redisStore = new RedisStore({ client: redisClient });

app.use(session({
  store: redisStore,
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false
}));

app.post('/api/support/sessions/:sessionId/touch', (req, res) => {
  if (!req.session || !req.session.userId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Only allow touching the current active session or by authorized support agents
  if (req.sessionID !== req.params.sessionId && req.session.role !== 'SUPPORT_OPERATOR') {
    return res.status(403).json({ error: 'Cannot keep alive an unassigned session' });
  }

  redisStore.get(req.params.sessionId, (getErr, targetSession) => {
    if (getErr || !targetSession) {
      return res.status(404).json({ error: 'Session not found' });
    }

    redisStore.touch(req.params.sessionId, targetSession, (err) => {
      if (err) {
        return res.status(500).json({ error: 'Failed to touch session' });
      }
      res.json({ status: 'Session TTL reset successfully' });
    });
  });
});

app.listen(8001);
